-- Тема 14: варианты ответов выровнены по длине и форме (56 исправлений в 18 вопросах), ключи не меняются.
-- Источник: scripts/questions/065_option_length_topic14.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('option', 'Какое преимущество у логической резервной копии?', 'Восстановление на любой момент времени', 'Её можно восстановить на любой момент после выгрузки', 'Восстановить можно только на момент копирования.', 'Восстановить можно только на момент выгрузки: журнала для продвижения дальше в логической копии нет.'),
        ('option', 'Какое преимущество у логической резервной копии?', 'Самое быстрое восстановление больших баз', 'Её восстанавливают быстрее, чем физическую копию', 'Восстановление медленное: выполняются все команды.', 'Восстановление медленное: выполняются все команды, индексы строятся заново.'),
        ('option', 'Какое преимущество у логической резервной копии?', 'Она содержит файлы WAL', 'Она содержит файлы WAL за время выгрузки', 'WAL в логической копии нет.', NULL),
        ('option', 'Какое преимущество у логической резервной копии?', 'Её можно восстановить на другой основной версии и другой архитектуре', 'Её можно восстановить на новой основной версии PostgreSQL', 'Нужна только совместимость на уровне команд SQL.', 'Нужна только совместимость на уровне команд SQL, поэтому подходят и другая основная версия, и другая архитектура.'),
        ('option', 'Чем \copy в psql отличается от SQL-команды COPY при работе с файлом?', '\copy всегда быстрее', '\copy работает быстрее COPY: данные идут в обход клиента', 'Данные идут через клиента, это не быстрее.', 'Наоборот, при \copy данные идут через клиента psql, это не быстрее.'),
        ('option', 'Чем \copy в psql отличается от SQL-команды COPY при работе с файлом?', '\copy работает с файлом на клиенте, COPY — с файлом на сервере', '\copy читает файл на клиенте, COPY — файл на сервере', 'Да. В случае \copy файл открывает клиент psql, в случае COPY с именем файла — сервер PostgreSQL.', NULL),
        ('option', 'Чем \copy в psql отличается от SQL-команды COPY при работе с файлом?', 'COPY поддерживает только CSV', 'COPY поддерживает формат CSV, а \copy — текстовый', 'COPY поддерживает форматы text, csv и binary.', 'Обе поддерживают форматы text, csv и binary: \copy передаёт параметры команде COPY.'),
        ('option', 'Чем \copy в psql отличается от SQL-команды COPY при работе с файлом?', 'Это одно и то же', '\copy и COPY работают с одним файлом на сервере', 'Они отличаются тем, где находится файл.', 'Файл для \copy открывает клиент psql на своей машине, а не сервер.'),
        ('option', 'Что дополнительно сохраняет pg_dumpall по сравнению с pg_dump?', 'Весь кластер, включая роли и табличные пространства', 'Роли и табличные пространства кластера', 'Роли и табличные пространства общие для кластера.', 'Роли и табличные пространства общие для кластера; кроме них pg_dumpall выгружает все базы.'),
        ('option', 'Что дополнительно сохраняет pg_dumpall по сравнению с pg_dump?', 'Файлы WAL', 'Файлы WAL, накопленные за время выгрузки', 'WAL сохраняет физическое копирование.', NULL),
        ('option', 'Что дополнительно сохраняет pg_dumpall по сравнению с pg_dump?', 'Физические файлы данных', 'Физические файлы данных всех баз кластера', 'Файлы данных копирует pg_basebackup.', NULL),
        ('option', 'Что дополнительно сохраняет pg_dumpall по сравнению с pg_dump?', 'Только одну схему', 'Одну выбранную схему вместе с её правами', 'Одну схему выгружает pg_dump -n.', NULL),
        ('option', 'Какое ограничение у физической резервной копии?', 'Нельзя восстановиться на момент времени', 'Нельзя восстановить кластер на выбранный момент времени', 'С архивом WAL можно восстановиться на нужный момент.', NULL),
        ('option', 'Какое ограничение у физической резервной копии?', 'Восстановление очень медленное', 'Восстановление идёт медленнее, чем из логической копии', 'Восстановление быстрое.', 'Восстановление быстрое: файлы копируются как есть.'),
        ('option', 'Какое ограничение у физической резервной копии?', 'Восстанавливается только весь кластер и только на той же основной версии и архитектуре', 'Восстанавливается весь кластер, на той же основной версии', 'Нужна двоичная совместимость.', 'Нужна двоичная совместимость: та же основная версия и та же архитектура; отдельную базу из физической копии не восстановить.'),
        ('option', 'Какое ограничение у физической резервной копии?', 'Для копирования нужно останавливать сервер', 'Для копирования приходится останавливать сервер', 'pg_basebackup снимает копию на работающем сервере.', NULL),
        ('option', 'Как pg_basebackup подключается к серверу?', 'Через команду COPY', 'Через SQL-команду COPY', 'COPY копирует данные таблиц, а не кластер.', NULL),
        ('option', 'Как pg_basebackup подключается к серверу?', 'По SSH', 'По SSH к машине сервера', 'SSH не используется.', 'SSH не используется: утилита подключается к самому серверу PostgreSQL.'),
        ('option', 'Как pg_basebackup подключается к серверу?', 'Через psql', 'Через обычный сеанс psql', 'psql — клиент для выполнения запросов.', NULL),
        ('option', 'Почему копия pg_basebackup с WAL называется автономной?', 'Создаётся без работающего сервера', 'Её можно снять без работающего сервера PostgreSQL', 'Копия делается на работающем сервере.', NULL),
        ('option', 'Почему копия pg_basebackup с WAL называется автономной?', 'Хранится на отдельном диске', 'Её хранят на отдельном диске, вне каталога данных', 'Место хранения роли не играет.', NULL),
        ('option', 'Почему копия pg_basebackup с WAL называется автономной?', 'Не требует WAL вообще', 'Для её восстановления журналы WAL не нужны вовсе', 'Наоборот, сегменты WAL входят в копию.', 'Наоборот: сегменты WAL входят в копию и применяются при запуске.'),
        ('option', 'Почему копия pg_basebackup с WAL называется автономной?', 'Содержит файлы кластера и все сегменты WAL за время копирования — всё для восстановления', 'Сегменты WAL за время копирования входят в неё', 'Дополнительный архив WAL не нужен; конфигурационные файлы вне каталога данных нужно восстановить отдельно.', 'Копия содержит файлы кластера и все сегменты WAL за время копирования, поэтому дополнительный архив не нужен. Конфигурационные файлы вне каталога данных восстанавливают отдельно.'),
        ('option', 'Что происходит, если archive_command завершилась с ненулевым статусом?', 'Сегмент удаляется', 'Сегмент удаляется, сервер переходит к следующему', 'Сегмент удаляется только после успешного копирования.', 'Сегмент удаляется только после успешного копирования в архив.'),
        ('option', 'Что происходит, если archive_command завершилась с ненулевым статусом?', 'Сервер останавливается', 'Сервер останавливается с ошибкой архивации', 'Сервер продолжает работать.', NULL),
        ('option', 'Что происходит, если archive_command завершилась с ненулевым статусом?', 'Сегмент WAL не удаляется, сервер периодически повторяет попытку', 'Сегмент остаётся в pg_wal, сервер повторяет попытку позже', 'Попытки повторяются, пока команда не вернёт 0.', 'Сегмент WAL не удаляется, попытки повторяются, пока команда не вернёт 0.'),
        ('option', 'Что происходит, если archive_command завершилась с ненулевым статусом?', 'Архивирование отключается', 'Архивирование отключается до перезапуска сервера', 'Архивирование не отключается.', NULL),
        ('option', 'Какой сигнальный файл запускает восстановление из архива, после которого сервер работает как обычный, а не как реплика?', 'postmaster.pid', 'postmaster.opts', 'Файл с номером процесса работающего сервера.', 'Файл с параметрами командной строки последнего запуска сервера.'),
        ('option', 'Что нужно, чтобы pg_basebackup мог подключиться по протоколу репликации?', 'archive_mode = on', 'archive_mode = on и заданная archive_command', 'Архивация для pg_basebackup не нужна.', NULL),
        ('option', 'Что нужно, чтобы pg_basebackup мог подключиться по протоколу репликации?', 'Атрибут REPLICATION у роли (или суперпользователь)', 'Роль с атрибутом REPLICATION', 'Право подключаться по протоколу репликации.', 'Право подключаться по протоколу репликации; подходит и суперпользователь.'),
        ('option', 'Что нужно, чтобы pg_basebackup мог подключиться по протоколу репликации?', 'wal_level = logical', 'wal_level = logical на основном сервере', 'Уровень logical не обязателен, достаточно replica.', NULL),
        ('option', 'Что позволяет ускорить копирование и восстановление большой базы данных утилитами pg_dump и pg_restore?', 'Использование утилиты pg_dumpall', 'Выгрузка утилитой pg_dumpall вместо pg_dump', 'Она выдаёт только скрипт для psql и параллельную выгрузку не поддерживает.', NULL),
        ('option', 'Что позволяет ускорить копирование и восстановление большой базы данных утилитами pg_dump и pg_restore?', 'Отключение журнала предзаписи', 'Отключение журнала предзаписи на время загрузки', 'Это не штатный способ ускорения восстановления.', NULL),
        ('option', 'Что позволяет ускорить копирование и восстановление большой базы данных утилитами pg_dump и pg_restore?', 'Копия в специальном формате с оглавлением и параллельное выполнение', 'Формат с оглавлением и параллельная работа (-j)', 'Восстанавливать параллельно можно копии в форматах custom и directory, выгружать параллельно — в формате directory.', NULL),
        ('option', 'Какие журналы предзаписи нужны, чтобы восстановить горячую копию файлов кластера?', 'Только последний сегмент журнала', 'Последний сегмент журнала перед началом копирования', 'Нужны все записи за время копирования.', NULL),
        ('option', 'Какие журналы предзаписи нужны, чтобы восстановить горячую копию файлов кластера?', 'Журналы не нужны, копия всегда согласована', 'Журналы не нужны: горячая копия уже согласована', 'Так бывает только при копировании остановленного сервера.', NULL),
        ('option', 'Какие журналы предзаписи нужны, чтобы восстановить горячую копию файлов кластера?', 'Только журналы после окончания копирования', 'Журналы, записанные после окончания копирования', 'Нужны записи за время копирования, начиная с контрольной точки.', NULL),
        ('option', 'Когда сегмент журнала попадает в файловый архив?', 'Только при остановке сервера', 'При остановке сервера, когда закрываются все сегменты', 'Архивация идёт непрерывно, по мере переключения сегментов.', NULL),
        ('option', 'Когда сегмент журнала попадает в файловый архив?', 'Сразу при записи каждой журнальной записи', 'Сразу после записи каждой журнальной записи на диск', 'Так работает потоковый архив, а не файловый.', NULL),
        ('option', 'Когда сегмент журнала попадает в файловый архив?', 'После того как сервер переключится на запись в следующий сегмент', 'Когда сервер переключится на следующий сегмент', 'Поэтому текущий сегмент в архив не попадает и возникают задержки.', 'Сервер передаёт в архив заполненный сегмент после переключения на следующий, поэтому текущий сегмент в архив не попадает и возникают задержки.'),
        ('option', 'Когда сегмент журнала попадает в файловый архив?', 'При каждой контрольной точке', 'При каждой контрольной точке, после сброса буферов', 'Момент определяется переключением сегмента, а не контрольной точкой.', NULL),
        ('option', 'Чем потоковый архив журналов, который ведёт pg_receivewal, отличается от файлового?', 'Записи пишутся в архив постоянно, не дожидаясь заполнения сегмента', 'Записи попадают в архив сразу, не дожидаясь конца сегмента', 'Поэтому задержки минимальны. Сбрасывать записи на диск сразу, а не при закрытии сегмента, утилита будет с ключом --synchronous.', NULL),
        ('option', 'Чем потоковый архив журналов, который ведёт pg_receivewal, отличается от файлового?', 'Он не требует подключения к серверу', 'Он читает сегменты из pg_wal, не подключаясь к серверу', 'Утилита подключается по протоколу репликации.', 'Утилита подключается к серверу по протоколу репликации.'),
        ('option', 'Чем потоковый архив журналов, который ведёт pg_receivewal, отличается от файлового?', 'Он хранит только заполненные сегменты', 'Он хранит заполненные сегменты, без текущего недописанного', 'Незаполненный сегмент хранится тоже, с суффиксом .partial.', NULL),
        ('option', 'Какой суффикс имеет файл незаполненного сегмента, который сейчас пишет pg_receivewal?', '.wip', '.history', 'Такого суффикса утилита не использует.', 'Так называются файлы истории линий времени, а не недописанный сегмент.'),
        ('option', 'Что задаёт параметр restore_command при восстановлении из архива?', 'Команду, которая копирует нужный сегмент WAL из архива в каталог сервера', 'Команду получения нужного сегмента WAL из архива', 'Это команда, обратная archive_command.', 'Это команда, обратная archive_command: копирует нужный сегмент WAL из архива в каталог сервера.'),
        ('option', 'Что задаёт параметр restore_command при восстановлении из архива?', 'Команду, которая создаёт базовую копию', 'Команду, которая создаёт базовую копию перед восстановлением', 'Базовую копию создаёт pg_basebackup.', NULL),
        ('option', 'Что задаёт параметр restore_command при восстановлении из архива?', 'Целевую точку восстановления', 'Целевую точку, до которой идёт восстановление', 'Целевая точка задаётся отдельными параметрами.', NULL),
        ('option', 'Какие потери возможны при восстановлении из архива, который наполнялся командой archive_command?', 'Только записи последней минуты', 'Записи последней минуты работы, независимо от нагрузки', 'Фиксированного срока нет: теряется то, что не успело попасть в архив.', NULL),
        ('option', 'Какие потери возможны при восстановлении из архива, который наполнялся командой archive_command?', 'Записи из незаполненного сегмента WAL, который не попал в архив', 'Записи незаполненного сегмента WAL, который не попал в архив', 'Если его нельзя скопировать вручную, он теряется.', NULL),
        ('option', 'Какие потери возможны при восстановлении из архива, который наполнялся командой archive_command?', 'Потерь не бывает', 'Потерь нет: архив содержит все записи WAL', 'Последний незаполненный сегмент остаётся вне архива.', NULL),
        ('option', 'Какие потери возможны при восстановлении из архива, который наполнялся командой archive_command?', 'Все записи после последней базовой копии', 'Все записи, сделанные после последней базовой копии', 'Заархивированные сегменты применяются, теряется только то, что в архив не попало.', NULL),
        ('option', 'Что нужно подготовить заранее, чтобы восстановить базу данных из SQL-дампа pg_dump, сделанного без ключа --create, на новом кластере, сохранив владельцев объектов и табличные пространства?', 'Пустую базу данных; рекомендуется создать её из шаблона template0', 'Пустую базу данных (лучше из template0)', 'Да. SQL-дамп без --create базу не создаёт. Шаблон template0 исключает пользовательские добавления, которые могли быть сделаны в template1: они вызвали бы конфликты при восстановлении.', NULL),
        ('option', 'Что нужно подготовить заранее, чтобы восстановить базу данных из SQL-дампа pg_dump, сделанного без ключа --create, на новом кластере, сохранив владельцев объектов и табличные пространства?', 'Табличные пространства', 'Табличные пространства, которые использует база', 'Они тоже относятся ко всему кластеру.', NULL),
        ('option', 'Что нужно подготовить заранее, чтобы восстановить базу данных из SQL-дампа pg_dump, сделанного без ключа --create, на новом кластере, сохранив владельцев объектов и табличные пространства?', 'Таблицы и индексы базы', 'Таблицы и индексы базы с прежней структурой', 'Их создаёт сама процедура восстановления.', NULL),
        ('option', 'Что верно для физической резервной копии?', 'При наличии архива журналов можно восстановить кластер на нужный момент времени', 'С архивом журналов можно восстановиться на нужный момент', 'Журналы применяются до целевой точки.', NULL)
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
